<script>
(function () {
  "use strict";

  /* ---------- Tiny math renderer (no external libs) ---------- */
  var SYM = {
    "\\lambda": "λ", "\\omega": "ω", "\\alpha": "α", "\\pi": "π",
    "\\theta": "θ", "\\sigma": "σ", "\\Omega": "Ω", "\\zeta": "ζ", "\\tau": "τ",
    "\\propto": "∝", "\\sim": "≈", "\\ll": "≪", "\\gg": "≫", "\\to": "→",
    "\\cdot": "·", "\\cos": "cos", "\\sin": "sin", "\\exp": "exp", "\\sec": "sec",
    "\\left": "", "\\right": ""
  };

  function toMath(s) {
    // 1) \frac{a}{b} -> sentinel tokens (single pass, no nested fracs needed)
    s = s.replace(/\\frac\{([^{}]*)\}\{([^{}]*)\}/g, "\u0001$1\u0002$2\u0003");
    // 2) braced sup/sub
    s = s.replace(/\^\{([^{}]*)\}/g, "<sup>$1</sup>");
    s = s.replace(/_\{([^{}]*)\}/g, "<sub>$1</sub>");
    // 3) single-char sup/sub
    s = s.replace(/\^([^\s{}])/g, "<sup>$1</sup>");
    s = s.replace(/_([^\s{}])/g, "<sub>$1</sub>");
    // 4) \mathbf{x} -> bold
    s = s.replace(/\\mathbf\{(\w)\}/g, "<b>$1</b>");
    // 5) remaining symbols
    for (var k in SYM) s = s.split(k).join(SYM[k]);
    // 6) restore fractions
    s = s.replace(/\u0001([^\u0002]*)\u0002([^\u0003]*)\u0003/g,
      '<span class="frac"><span class="fn">$1</span><span class="fd">$2</span></span>');
    return s;
  }

  var mathEls = document.querySelectorAll("[data-math]");
  for (var i = 0; i < mathEls.length; i++) {
    mathEls[i].innerHTML = toMath(mathEls[i].getAttribute("data-math"));
  }

  /* ---------- Language toggle ---------- */
  var buttons = document.querySelectorAll(".toggle button");
  function setLang(lang) {
    document.body.setAttribute("data-lang", lang);
    for (var i = 0; i < buttons.length; i++) {
      var on = buttons[i].getAttribute("data-lang") === lang;
      buttons[i].classList.toggle("active", on);
      buttons[i].setAttribute("aria-pressed", on ? "true" : "false");
    }
  }
  for (var i = 0; i < buttons.length; i++) {
    (function (btn) {
      btn.addEventListener("click", function () { setLang(btn.getAttribute("data-lang")); });
    })(buttons[i]);
  }

  /* ---------- Scroll-spy for section nav ---------- */
  var links = document.querySelectorAll(".nav a");
  if ("IntersectionObserver" in window) {
    var spy = new IntersectionObserver(function (entries) {
      entries.forEach(function (e) {
        if (e.isIntersecting) {
          var sec = e.target.getAttribute("data-sec");
          links.forEach(function (l) {
            l.classList.toggle("active", l.getAttribute("data-sec") === sec);
          });
        }
      });
    }, { rootMargin: "-35% 0px -55% 0px" });
    var enPanels = document.querySelectorAll(".panel.en");
    for (var j = 0; j < enPanels.length; j++) spy.observe(enPanels[j]);
  }
})();
</script>
</body>
