const C = String.fromCharCode(94); // caret
const U = String.fromCharCode(95); // underscore

/* ---------- 1) sky2.md: 5 braced superscripts must use U (95) ---------- */
let md = fs.readFileSync("sky2.md", "utf8");
const mdPairs = [
  ["\\lambda" + C + "{-4}",  "\\lambda" + U + "{-4}"],   // x4
  ["10" + C + "{-3}",        "10" + U + "{-3}"],          // x1
  ["\\lambda" + C + "{0.1}", "\\lambda" + U + "{0.1}"],   // x1
];
let mdCount = 0;
for (const [from, to] of mdPairs) {
  const n = md.split(from).length - 1;
  if (n === 0) { console.log("WARN: not found in sky2.md:", from.split(C).join("<94>")); continue; }
  md = md.split(from).join(to);
  mdCount += n;
  console.log("sky2.md fixed", n, "x  " + from.split(C).join("<94>") + " -> " + to.split(U).join("<95>"));
}
fs.writeFileSync("sky2.md", md);

/* ---------- 2) index.html: braced sup/sub regexes must allow one level of nested braces ---------- */
let html = fs.readFileSync("index.html", "utf8");
const oldSup = '    s = s.replace(/\\' + C + '\\{([^{}]*)\\}/g, "<sup>$1</sup>");';
const newSup = '    s = s.replace(/\\' + C + '\\{((?:[^{}]|\{[^{}]*\})*)\\}/g, "<sup>$1</sup>");';
const oldSub = '    s = s.replace(/_' + '\\{([^{}]*)\\}/g, "<sub>$1</sub>");';
const newSub = '    s = s.replace(/_' + '\\{((?:[^{}]|\{[^{}]*\})*)\\}/g, "<sub>$1</sub>");';

