if (nSup4 !== 4) fails.push("sky2.md lambda^{-4} count: " + nSup4 + " (want 4)");
checkMd("10" + String.fromCharCode(94) + "{-3}", 94);
checkMd("lambda" + String.fromCharCode(94) + "{0.1}", 94);
// plain subscripts (95=underscore): N_2, O_2, omega_0
for (const t of ["N" + String.fromCharCode(95) + "2", "O" + String.fromCharCode(95) + "2", "omega" + String.fromCharCode(95) + "0"]) {
