const fs = require("fs");
const en = fs.readFileSync("sky.md", "utf8");
const zh = fs.readFileSync("sky2.md", "utf8");

function parse(md) {
  const lines = md.split("\n");
  const title = lines.find(l => l.startsWith("# "));
  // sections: split by "## "
  const sections = [];
  let cur = null;
  for (const line of lines) {
    if (line.startsWith("## ")) {
      if (cur) sections.push(cur);
      cur = { heading: line.slice(3), body: [] };
    } else if (cur) {
      cur.body.push(line);
    }
  }
  if (cur) sections.push(cur);
  return { title: title.slice(2), sections };
}

const E = parse(en), Z = parse(zh);
if (E.sections.length !== 3 || Z.sections.length !== 3) throw new Error("section count");

let out = "# " + E.title + " · " + Z.title + "\n\n";
for (let i = 0; i < 3; i++) {
  const eb = E.sections[i].body.join("\n").replace(/\n+$/, "");
  const zb = Z.sections[i].body.join("\n").replace(/\n+$/, "");
  out += "## " + E.sections[i].heading + "\n\n" + eb + "\n\n" +
         "### " + Z.sections[i].heading + "\n\n" + zb + "\n\n";
}
fs.writeFileSync("sky_bilingual.md", out.replace(/\n+$/, "") + "\n");
