// Structure: bilingual H1, then per level: ## English heading + body, ### Chinese heading + body.
// All content is copied byte-for-byte from the source files (no re-typing).
const fs = require("fs");
const en = fs.readFileSync("sky.md", "utf8");
const zh = fs.readFileSync("sky2.md", "utf8");

function parse(md) {
  const lines = md.split("\n");
  const t = lines.find(l => l.startsWith("# "));
  if (!t) throw new Error("no H1 title");
  const sections = [];
  let cur = null;
  for (const line of lines) {
    if (line.startsWith("## ")) {
      if (cur) sections.push(cur);
      cur = { heading: line.slice(3), body: [] };
    } else if (cur) {
      cur.body.push(line);
    }
  }
  if (cur) sections.push(cur);
  if (sections.length !== 3) throw new Error("expected 3 sections, got " + sections.length);
  return { title: t.slice(2).trim(), sections };
}

const E = parse(en);
const Z = parse(zh);

let out = "# " + E.title + " \u00b7 " + Z.title + "\n\n";
for (let i = 0; i < 3; i++) {
  const eb = E.sections[i].body.join("\n").replace(/\n+$/, "");
  const zb = Z.sections[i].body.join("\n").replace(/\n+$/, "");
  if (!eb || !zb) throw new Error("empty body at level " + (i + 1));
  out += "## " + E.sections[i].heading + "\n\n" + eb + "\n\n" +
         "### " + Z.sections[i].heading + "\n\n" + zb + "\n\n";
}
out = out.replace(/\n+$/, "") + "\n";
fs.writeFileSync("sky_bilingual.md", out);

// ---- verify: every source line survives verbatim in the merged file ----
const merged = fs.readFileSync("sky_bilingual.md", "utf8");
let missing = 0;
for (const f of ["sky.md", "sky2.md"]) {
  for (const line of fs.readFileSync(f, "utf8").split("\n")) {
    if (!line || line.startsWith("#")) continue; // title/headings handled separately
    if (merged.indexOf(line) === -1) { missing++; console.log("MISSING from", f, ":", line.slice(0, 60)); }
  }
}
console.log(missing === 0 ? "all non-heading source lines preserved" : missing + " lines lost");

// verify math superscript bytes (94=caret) survived in merged file
const CAR = String.fromCharCode(94);
let nSup4 = 0; { let i = -1; const t = "lambda" + CAR + "{-4}"; while ((i = merged.indexOf(t, i + 1)) !== -1) nSup4++; }
console.log("merged lambda-caret-{ -4 } count:", nSup4, "(expect 6: 3 EN + 3 ZH)");
console.log("merged 10-caret-{ -3 } present:", merged.indexOf("10" + CAR + "{-3}") !== -1 ? "yes x2 expected" : "NO");
const n10 = merged.split("10" + CAR + "{-3}").length - 1;
console.log("merged 10^-3 count:", n10, "(expect 2)");

// structure
const h1 = (merged.match(/^# /gm) || []).length;
const h2 = (merged.match(/^## /gm) || []).length;
const h3 = (merged.match(/^### /gm) || []).length;
console.log("headings: H1=" + h1 + " (expect 1), H2=" + h2 + " (expect 3 EN), H3=" + h3 + " (expect 3 ZH)");

if (missing !== 0 || nSup4 !== 6 || n10 !== 2 || h1 !== 1 || h2 !== 3 || h3 !== 3) {
  console.log("VERIFICATION FAILED - not deleting sources");
  process.exit(1);
}
console.log("VERIFICATION PASSED");
