{"content": "const fs = require("fs");
const html = fs.readFileSync("earth.html", "utf8");
let fails = [];

// 1) JS syntax
try {
  new Function(html.match(/<script>([\s\S]*?)<\/script>/)[1]);
} catch (e) { fails.push("JS syntax error: " + e.message); }

// 2) SVG arc geometry: every 'A r r 0 0 f x2 y2' endpoint must sit on circle centered (250,210)
const cx = 250, cy = 210;
const svg = html.match(/<svg[\s\S]*?<\/svg>/)[0];
const arcs = [...svg.matchAll(/A\s+(\d+(?:\.\d+)?)\s+\1\s+0\s+0\s+\d\s+([\d.]+)\s+([\d.]+)/g)];
for (const m of arcs) {
  const r = parseFloat(m[1]), x = parseFloat(m[2]), y = parseFloat(m[3]);
  const d = Math.hypot(x - cx, y - cy);
  if (Math.abs(d - r) > 0.01) fails.push(`arc r=${r} endpoint (${x},${y}) distance ${d.toFixed(2)} != r`);
}
console.log("arcs checked:", arcs.length);

// expected radius set: 170 (x3: surface half, crust outer), 152 (x2), 92 (x2), 52 (x2)
const radii = arcs.map(m => m[1]).sort((a, b) => a - b);
console.log("arc radii:", radii.join(", "));
if (new Set(radii).size !== 4) fails.push("expected 4 distinct radii");

// 3) layer path radius consistency: crust outer 170 inner 152; mantle 152/92; outer 92/52; inner 52
const layers = [...svg.matchAll(/class="layer" data-layer="(\w+)" d="([^"]+)"/g)];
const expect = { crust: [170, 152], mantle: [152, 92], outer: [92, 52], inner: [52] };
for (const m of layers) {
  const rs = [...m[2].matchAll(/A\s+(\d+)/g)].map(x => parseInt(x[1], 10));
  const want = expect[m[1]];
  if (!want || rs.length !== want.length || rs.some((r, i) => r !== want[i]))
    fails.push(`layer ${m[1]} radii: ${rs.join(",")} want ${want}`);
}
console.log("layer radii OK for:", layers.map(m => m[1]).join(", "));

// 4) every data-layer in SVG has a matching card, and vice versa
const svgLayers = [...new Set([...svg.matchAll(/data-layer="(\w+)"/g)].map(m => m[1]))];
const cardLayers = [...new Set([...html.matchAll(/class="card" data-layer="(\w+)"/g)].map(m => m[1]))];
if (JSON.stringify(svgLayers.sort()) !== JSON.stringify(cardLayers.sort()))
  fails.push("layer mismatch svg=" + svgLayers + " cards=" + cardLayers);

// 5) tag balance for key elements
for (const tag of ["section", "article", "div", "svg", "defs", "dl"]) {
  const open = (html.match(new RegExp("<" + tag + "[\\s>]", "g")) || []).length;
  const close = (html.match(new RegExp("</" + tag + ">", "g")) || []).length;
  if (open !== close) fails.push(`unbalanced <${tag}>: ${open} open vs ${close} close`);
}

// 6) RTL + Arabic sanity
if (!html.includes('dir="rtl"') || !html.includes('lang="ar"')) fails.push("missing rtl/ar attributes");
const arabicChars = (html.match(/[\u0600-\u06FF]/g) || []).length;
console.log("arabic chars:", arabicChars);
if (arabicChars < 400) fails.push("suspiciously few arabic characters");
if (!html.includes("https://") && !html.includes("http://")) console.log("no external URLs: confirmed");
else fails.push("found external URL");

if (fails.length) { console.log("FAILURES:"); fails.forEach(f => console.log(" -", f)); process.exit(1); }
console.log("ALL CHECKS PASSED");
