{"content": "// QA pass: verify lang attr, charset, and author footer on every HTML file.
const fs = require("fs");
const files = { "index.html": "en", "earth.html": "ar" };
let allOk = true;

for (const [file, wantLang] of Object.entries(files)) {
  const html = fs.readFileSync(file, "utf8");
  const issues = [];

  // (1) <html lang="...">
  const htmlTag = html.match(/<html[^>]*>/);
  if (!htmlTag) issues.push("missing <html> tag");
  else if (!new RegExp('lang="' + wantLang + '"').test(htmlTag[0]))
    issues.push("lang should be \"" + wantLang + "\" but tag is: " + htmlTag[0]);

  // (2) <meta charset="utf-8"> (exact lowercase form)
  if (!html.includes('<meta charset="utf-8">')) issues.push('missing <meta charset="utf-8">');

  // (3) author footer, exact element, at the bottom (last footer in the file)
  const authorTag = '<footer id="author">Created by Dr. Jennifer Robins - 2026</footer>';
  const lastFooterEnd = html.lastIndexOf("</footer>");
  const authorStart = html.lastIndexOf(authorTag);
  if (authorStart === -1) issues.push("missing exact author footer element");
  else {
    if (html.slice(authorStart + authorTag.length, lastFooterEnd).trim() !== "")
      issues.push("author footer is not the last footer in the file");
    // must come after all <main> content
    if (html.lastIndexOf("</main>") > authorStart) issues.push("author footer appears before </main>");
  }

  console.log("=== " + file + " ===");
  if (issues.length) { allOk = false; issues.forEach(i => console.log("  FAIL:", i)); }
  else {
    console.log("  PASS: lang=\"" + wantLang + "\"  charset  author-footer (last, after content)");
  }
  console.log("");
}

process.exit(allOk ? 0 : 1);
