_BISHOP_DIRS = ((-1, -1), (-1, 1), (1, -1), (1, 1))


def _square_name(row, col):
    """Square name; row 0 = rank 8 (top of board), col 0 = file a."""
    return chr(97 + col) + str(8 - row)


def _square_index(square):
    col = ord(square[0]) - 97
    row = 8 - int(square[1])
