    for dirs, kinds in ((_ROOK_DIRS, "rq"), (_BISHOP_DIRS, "bq")):
        for dr, dc in dirs:
            r, c = row + dr, col + dc
            while 0 <= r < 8 and 0 <= c < 8:
                p = board[r * 8 + c]
                if p is not None:
                    if p.isupper() == by_white and p.lower() in kinds:
                        return True
                    break
                r += dr
                c += dc
    return False


def _castling_moves(board, white, king_idx, castling, moves):
    enemy = not white
    expected_rook = "R" if white else "r"
    for right, (king_sq, rook_sq, empty_sqs, safe_sqs) in _CASTLING.items():
        if right not in castling or king_idx != king_sq:
            continue
        if board[rook_sq] != expected_rook:
            continue
        if any(board[s] is not None for s in empty_sqs):
            continue
        if any(_is_attacked(board, s, enemy) for s in safe_sqs):
            continue
        row, col = divmod(king_sq, 8)
        dst_col = col + 2 if right in ("K", "k") else col - 2
        moves.append(_square_name(row, col) + _square_name(row, dst_col))


def _pawn_moves(board, white, row, col, ep, moves):
    forward = -1 if white else 1
    start_row = 6 if white else 1
    last_row = 0 if white else 7
    one = row + forward
    origin = _square_name(row, col)
    if 0 <= one < 8:
        # single push (and double push from the start rank);
        # reaching the final rank offers all four promotions
        if board[one * 8 + col] is None:
            dest = _square_name(one, col)
            if one == last_row:
                moves.extend(origin + dest + pc for pc in _PROMOTIONS)
            else:
                moves.append(origin + dest)
                if row == start_row and board[(one + forward) * 8 + col] is None:
                    moves.append(origin + _square_name(one + forward, col))
        # captures (incl. en passant onto the FEN target square)
        for cap_col in (col - 1, col + 1):
            if not 0 <= cap_col < 8:
                continue
            target_idx = one * 8 + cap_col
            if _is_enemy(board[target_idx], white):
                dest = _square_name(one, cap_col)
                if one == last_row:
                    moves.extend(origin + dest + pc for pc in _PROMOTIONS)
                else:
                    moves.append(origin + dest)
            elif ep is not None and ep == target_idx:
                # the victim pawn sits beside us on our own rank
                victim = board[row * 8 + cap_col]
                if _is_enemy(victim, white) and victim.lower() == "p":
                    moves.append(origin + _square_name(one, cap_col))


def _step_moves(board, white, row, col, offsets, moves):
    origin = _square_name(row, col)
    for dr, dc in offsets:
        rr, cc = row + dr, col + dc
        if 0 <= rr < 8 and 0 <= cc < 8:
            target = board[rr * 8 + cc]
            if target is None or _is_enemy(target, white):
                moves.append(origin + _square_name(rr, cc))


def _slide_moves(board, white, row, col, dirs, moves):
    origin = _square_name(row, col)
    for dr, dc in dirs:
        rr, cc = row + dr, col + dc
        while 0 <= rr < 8 and 0 <= cc < 8:
            target = board[rr * 8 + cc]
            if target is None:
                moves.append(origin + _square_name(rr, cc))
            else:
                if _is_enemy(target, white):
                    moves.append(origin + _square_name(rr, cc))
                break
            rr += dr
            cc += dc


def legal_moves(fen: str) -> list[str]:
    """All (pseudo-)moves for the side to move, in UCI notation.

    Castling is fully legal (no castling out of, through, or into
    check, and the path must be clear), en passant honours the FEN
    target square, and pawn moves to the final rank are emitted with
    all four UCI promotion suffixes. Check/pin filtering for
    ordinary moves is still unimplemented, so non-castling moves
    may expose the king to check.
    """
    board, white_to_move, castling, ep = _parse_fen(fen)
    moves = []
    for idx in range(64):
        piece = board[idx]
        if piece is None or piece.isupper() != white_to_move:
            continue
        row, col = divmod(idx, 8)
        kind = piece.lower()
        if kind == "p":
            _pawn_moves(board, white_to_move, row, col, ep, moves)
        elif kind == "n":
            _step_moves(board, white_to_move, row, col, _KNIGHT_OFFSETS, moves)
        elif kind == "k":
            _step_moves(board, white_to_move, row, col, _KING_OFFSETS, moves)
            _castling_moves(board, white_to_move, idx, castling, moves)
        elif kind == "q":
            _slide_moves(board, white_to_move, row, col,
                         _ROOK_DIRS + _BISHOP_DIRS, moves)
        elif kind == "r":
            _slide_moves(board, white_to_move, row, col, _ROOK_DIRS, moves)
        else:  # bishop
            _slide_moves(board, white_to_move, row, col, _BISHOP_DIRS, moves)
    return moves


def _board_to_placement(board):
    ranks = []
    for row in range(8):
        out, empty = [], 0
        for col in range(8):
            piece = board[row * 8 + col]
            if piece is None:
                empty += 1
            else:
                if empty:
                    out.append(str(empty))
                    empty = 0
                out.append(piece)
        if empty:
            out.append(str(empty))
        ranks.append("".join(out))
    return "/".join(ranks)


def _new_castling_rights(castling, piece, src, dst, captured):
    rights = set(castling)
    if piece == "K":
        rights.difference_update("KQ")
    elif piece == "k":
        rights.difference_update("kq")
    if src in _ROOK_HOME:
        rights.discard(_ROOK_HOME[src])
    if captured is not None and dst in _ROOK_HOME:
        rights.discard(_ROOK_HOME[dst])
    return "".join(c for c in "KQkq" if c in rights) or "-"


def _apply_move(fen: str, move: str) -> str:
    board, turn, castling, ep = _parse_fen(fen)
    src, dst = _square_index(move[:2]), _square_index(move[2:4])
    piece = board[src]
    captured = board[dst]
    # castling also moves the rook
    if piece in ("K", "k") and abs(dst - src) == 2:
        base = (src // 8) * 8
        if dst > src:  # kingside: rook h -> f
            board[base + 5] = board[base + 7]
            board[base + 7] = None
        else:          # queenside: rook a -> d
            board[base + 3] = board[base]
            board[base] = None
    # en passant removes the victim pawn beside the destination
    if piece.lower() == "p" and captured is None and dst == ep:
        board[dst + 8 if piece == "P" else dst - 8] = None
    # promotion changes the pawn's piece type
    if piece.lower() == "p" and len(move) > 4 and move[4] in "qrbn":
        piece = move[4].upper() if piece == "P" else move[4]
    board[dst] = piece
    board[src] = None
    parts = fen.split()
    parts[0] = _board_to_placement(board)
    parts[1] = "b" if turn else "w"
    if len(parts) > 2:
        parts[2] = _new_castling_rights(castling, piece, src, dst, captured)
    if len(parts) > 3:
        # only a pawn double push creates a new en passant square
        if piece == "P" and dst == src - 16:
            parts[3] = _square_name(src // 8 - 1, src % 8)
        elif piece == "p" and dst == src + 16:
            parts[3] = _square_name(src // 8 + 1, src % 8)
        else:
            parts[3] = "-"
    return " ".join(parts)


def perft(fen: str, depth: int) -> int:
    """Number of leaf nodes at the given depth (perft(0) == 1)."""
    if depth == 0:
        return 1
    nodes = 0
    for move in legal_moves(fen):
        nodes += perft(_apply_move(fen, move), depth - 1)
    return nodes

